#include "core/SampleDatabase.h"
int main(){auto f=juce::File::getSpecialLocation(juce::File::tempDirectory).getChildFile("magdrum-test.sqlite3");f.deleteFile();SampleDatabase db;if(!db.open(f))return 1;auto sample=f.getSiblingFile("kick.wav");if(!db.insertSample(sample,0.2,1,44100))return 2;if(!db.insertSample(sample,0.2,1,44100))return 3;auto paths=db.getAllPaths();if(paths.size()!=1||paths.getFirst()!=sample)return 4;return 0;}
